{
  "items": [
    {
      "title": "German Time Use Survey 2001/2002 (Zeitbudgeterhebung) – Scientific Use File",
      "url_or_doi": "https://doi.org/10.21242/63911.2002.00.00.3.1.0",
      "justification": "Highly relevant for studying time use during the 2000s. Conducted in 2001–2002, this nationwide survey records how individuals allocate their time across employment, household activities, childcare, education, leisure, and other daily activities. It includes time-use diaries and socioeconomic information from 5,161 households. However, the Scientific Use File only identifies broad German regions, so Duisburg-specific analysis is not possible using this version."
    },
    {
      "title": "German Time Use Survey 2001/2002 – On-Site Microdata",
      "url_or_doi": "https://doi.org/10.21242/63911.2002.00.00.1.1.0",
      "justification": "An alternative version of the German Time Use Survey 2001/2002, available through the Research Data Centres of the Federal and State Statistical Offices. It contains detailed information about daily activities, including paid work, unpaid work, leisure, education, and household responsibilities. Researchers interested in Duisburg could investigate whether sufficiently detailed geographical identifiers are available under restricted access. Duisburg-level identification is not guaranteed."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2000 (Duisburger Bürgerumfrage Herbst 2000)",
      "url_or_doi": "https://doi.org/10.4232/1.3469",
      "justification": "A geographically specific dataset covering Duisburg residents aged 18–75, surveyed between October and November 2000. It provides information about residents' living conditions and attitudes. It may offer contextual variables relevant to leisure, employment, and everyday activities, although detailed time-use diary information has not been confirmed. Particularly valuable because it directly covers Duisburg at the beginning of the 2000s."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2004, German Population",
      "url_or_doi": "https://b2find.eudat.eu/dataset/b77f0ad4-c6e5-5732-bf30-494455ad5824",
      "justification": "A particularly relevant Duisburg-specific dataset from 2004. It includes information about the frequency with which residents visit recreational, educational, and cultural facilities and participate in leisure activities. It also covers employment, household characteristics, public transportation, and satisfaction with local amenities. Useful for investigating leisure-time activities and everyday lifestyles in Duisburg during the mid-2000s. It measures participation frequency rather than precise time spent."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2005, German Population",
      "url_or_doi": "https://doi.org/10.4232/1.4516",
      "justification": "A survey of German residents aged 18–75 living in Duisburg in 2005. It examines adult education, leisure preferences, participation in educational activities, and barriers related to professional workload, course scheduling, and competing leisure opportunities. Particularly useful for examining how employment commitments, educational participation, and leisure preferences interacted during the 2000s. It is not a comprehensive daily time-use survey."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2005, Foreign Population",
      "url_or_doi": "https://b2find.eudat.eu/dataset/b8279c06-262f-5cf3-ae80-2a21a4378af4",
      "justification": "A complementary 2005 survey focusing on foreign residents of Duisburg. It includes questions about leisure activities, educational participation, professional responsibilities, and barriers to attending adult education programs. Useful for comparing leisure preferences and constraints across population groups in Duisburg during the mid-2000s. The dataset does not provide comprehensive time-use diaries."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2002, German Population",
      "url_or_doi": "https://doi.org/10.4232/1.4346",
      "justification": "A Duisburg-specific population survey conducted in autumn 2002. It provides a potential source for investigating residents' socioeconomic circumstances and everyday living conditions in the early 2000s. It could complement the German Time Use Survey when studying Duisburg. The availability of direct time-use measurements or leisure-duration variables requires verification."
    },
    {
      "title": "Harmonised European Time Use Survey – 2000 and 2010",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/tus_00_esms.htm",
      "justification": "Eurostat's harmonised time-use statistics provide internationally comparable information about daily activities, including employment, household work, personal care, and leisure. Germany participated in the 2000 survey wave using data collected in 2001–2002. This source is useful for establishing broader time-use patterns against which Duisburg could be compared. However, the published harmonised statistics do not provide Duisburg-specific observations."
    },
    {
      "title": "Syntax for Creating a Comparative Dataset on Parents' Time Use in Four Countries, 2000–2003",
      "url_or_doi": "https://doi.org/10.3886/ICPSR30021.v1",
      "justification": "An ICPSR research resource designed to harmonise parental time-use data from Germany, Norway, the United Kingdom, and the United States. The German component uses the 2001–2002 time-use survey. It is particularly useful for studying time devoted to childcare and family responsibilities during the early 2000s. This resource provides harmonisation syntax rather than a standalone Duisburg dataset, and the underlying German data must be obtained separately."
    }
  ]
}
